 "content": "from collections import Counter


def transform(grid):
    """Restore cells overwritten by 3 using the grid's 180-degree symmetry."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            a = (r, c)
            b = (h - 1 - r, w - 1 - c)
            if a in seen:
                continue
            seen.add(a)
            seen.add(b)
            va, vb = grid[r][c], grid[b[0]][b[1]]
            if va != 3 and vb != 3:
                continue
            if va == 3 and vb != 3:
                value = vb
            elif vb == 3 and va != 3:
                value = va
            else:
                # If both symmetric cells were covered, infer their common
                # value from the closest visible neighbors around both cells.
                counts = Counter()
                for rr, cc in (a, b):
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 3:
                            counts[grid[nr][nc]] += 1
                if counts:
                    value = counts.most_common(1)[0][0]
                else:
                    # Expand outward until the nearest visible ring is found.
                    candidates = []
                    for rr, cc in (a, b):
                        for nr in range(h):
                            for nc in range(w):
                                d = abs(nr - rr) + abs(nc - cc)
                                if d and grid[nr][nc] != 3:
                                    candidates.append((d, grid[nr][nc]))
                    nearest = min(d for d, _ in candidates)
                    counts = Counter(v for d, v in candidates if d == nearest)
                    value = counts.most_common(1)[0][0]
            out[r][c] = value
            out[b[0]][b[1]] = value
    return out
